-cos-general-type=3D"widge=\r\nt" data-hs-cos-type=3D"module"><table role=3D"none" border=3D"0" cellpaddin=\r\ng=3D"0" cellspacing=3D"0" style=3D"vertical-align:top" width=3D"100%">\r\n  <tbody><tr>\r\n    <td align=3D"center" style=3D"font-family:Arial, sans-serif; color:#333=\r\n645; font-size:0; word-break:break-word">\r\n      <p style=3D"font-size:1px;border-top:1px solid #EEEEEE;width:100%;mar=\r\ngin:0 auto;"></p>\r\n      <!--[if mso]>\r\n        <table role=3D"none" align=3D"center" border=3D"0" cellpadding=3D"0=\r\n" cellspacing=3D"0" style=3D"font-size:1px;border-top:1px solid #EEEEEE;wid=\r\nth:600px;">\r\n          <tr>\r\n            <td style=3D"height:0;line-height:0">&nbsp;</td>\r\n          </tr>\r\n        </table>\r\n      <![endif]-->\r\n    </td>\r\n  </tr>\r\n</tbody></table></div></td></tr></tbody></table>\r\n</div>\r\n<!--[if gte mso 9]></table><![endif]-->\r\n<!--[if (mso)|(IE)]></td><![endif]-->\r\n    <!--[if (mso)|(IE)]></tr></table><![endif]-->\r\n    </div>\r\n  =20\r\n  </div>\r\n  <div id=3D"section-9" class=3D"hse-section" style=3D"padding-left:10px; p=\r\nadding-right:10px">\r\n   =20\r\n   =20\r\n      <div class=3D"hse-column-container" style=3D"min-width:280px; max-wid=\r\nth:600px; margin:0 auto; background-color:#ffffff; padding-bottom:20px; pad=\r\nding-top:10px" bgcolor=3D"#ffffff">\r\n   =20\r\n    <!--[if (mso)|(IE)]>\r\n      <table align=3D"center" style=3D"width:600px;" cellpadding=3D"0" cell=\r\nspacing=3D"0" role=3D"presentation" width=3D"600" bgcolor=3D"#ffffff">\r\n      <tr style=3D"background-color:#ffffff;">\r\n    <![endif]-->\r\n    <!--[if (mso)|(IE)]>\r\n  <td valign=3D"middle" style=3D"width:600px;padding-bottom:20px; padding-t=\r\nop:10px;">\r\n<![endif]-->\r\n<!--[if gte mso 9]>\r\n  <table role=3D"presentation" width=3D"600" cellpadding=3D"0" cellspacing=\r\n=3D"0" style=3D"width:600px">\r\n<![endif]-->\r\n<div id=3D"column-9-0" class=3D"hse-column hse-size-12" style=3D"vertical-a=\r\nlign: middle;">\r\n    <table role=3D"presentation" cellpadding=3D"0" cellspacing=3D"0" width=\r\n=3D"100%" class=3D"" style=3D""><tbody><tr><td class=3D"hs_padded" style=3D=\r\n"font-family:Arial, sans-serif; font-size:14px; color:#333645; word-break:b=\r\nreak-word; padding:20px 30px 10px"><div id=3D"hs_cos_wrapper_module-9-0-0" =\r\nclass=3D"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" s=\r\ntyle=3D"color: inherit; font-size: inherit; line-height: inherit;" data-hs-=\r\ncos-general-type=3D"widget" data-hs-cos-type=3D"module"><div id=3D"hs_cos_w=\r\nrapper_module-9-0-0_" class=3D"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_=\r\nwrapper_type_rich_text" style=3D"color: inherit; font-size: inherit; line-h=\r\neight: inherit;" data-hs-cos-general-type=3D"widget" data-hs-cos-type=3D"ri=\r\nch_text"><h2 style=3D"margin:0; line-height:175%; font-size:18px; color:#00=\r\n686e">=F0=9F=93=88 Watch three signals, not just one</h2>\r\n<p style=3D"line-height:175%">High-demand dates rarely announce themselves.=\r\n Look for:</p>\r\n<ul style=3D"line-height:175%">\r\n<li><span style=3D"color: #fb6214;"><strong>Booking pace:</strong></span> A=\r\nre you picking up faster than at this point last year? If a date had two re=\r\nservations then and has six now, something is driving demand.</li>\r\n<li><span style=3D"color: #fb6214;"><strong>Local events:</strong> </span>C=\r\noncerts, festivals, trade fairs and school breaks. Check your event calenda=\r\nr every week.</li>\r\n<li><span style=3D"color: #fb6214;"><strong>Competitor behavior:</strong></=\r\nspan> Rising rates or sell-outs nearby are a prompt to look closer at your =\r\nown dates.</li>\r\n</ul>\r\n<h2 style=3D"margin:0; line-height:175%; font-size:18px; color:#00686e">=F0=\r\n=9F=97=93=EF=B8=8F Make it a weekly habit (under an hour)</h2>\r\n<ul style=3D"line-height:175%">\r\n<li><span style=3D"color: #fb6214;"><strong>Monday (15 to 20 min):</strong>=\r\n</span> Scan the next 30 to 60 days of reservations. Compare pickup to last=\r\n year and check events for the same dates.</li>\r\n<li><span style=3D"color: #fb6214;"><strong>Mid-week (5 to 10 min):</strong=\r\n></span> Check competitor rates on the OTAs for the dates you flagged.</li>\r\n<li><span style=3D"color: #fb6214;"><strong>End of week (10 min):</strong> =\r\n</span>Decide on a rate move before the weekend. Even a small step up beats=\r\n waiting.</li>\r\n</ul>\r\n<ul style=3D"line-height:175%"></ul>\r\n<h2 style=3D"margin:0; line-height:175%; font-size:18px; color:#00686e">=F0=\r\n=9F=AA=9C Raise rates in steps</h2>\r\n<p style=3D"line-height:175%">Test the market with a <span style=3D"color: =\r\n#fb6214;"><strong>small increase first</strong>.</span> A sudden spike can =\r\npush early bookers to competitors. When your best nights start filling up, =\r\na two-night minimum on Friday and Saturday can help you avoid losing Sunday=\r\n. Keep your bigger rate moves for dates where bookings are strong, there=E2=\r\n=80=99s a clear local reason for demand, and competitors are filling up too=\r\n.</p>\r\n<div style=3D"line-height:175%; width:100%">\r\n<div style=3D"line-height:175%; height:0px" height=3D"0">&nbsp;</div>\r\n</div>\r\n<ul style=3D"line-height:175%"></ul>\r\n<h2 style=3D"margin:0; line-height:175%; font-size:18px; color:#00686e">=F0=\r\n=9F=8E=AF Use competitor rates as a prompt, not a rule</h2>\r\n<ul style=3D"line-height:175%"></ul>\r\n<p style=3D"line-height:175%">A competitor selling out at =E2=82=AC150 show=\r\ns demand is there. It doesn=E2=80=99t set <span style=3D"color: #fb6214;"><=\r\nstrong>your</strong> </span>price, because their occupancy, costs and room =\r\nmix differ from yours. If your pickup is strong, your ceiling may be higher=\r\n. After each busy period, compare actual occupancy, ADR and RevPAR with wha=\r\nt you expected.</p>\r\n<ul style=3D"line-height:175%"></ul>\r\n<ul style=3D"line-height:175%"></ul></div></div></td></tr></tbody></table>\r\n</div>\r\n<!--[if gte mso 9]></table><![endif]-->\r\n<!--[if (mso)|(IE)]></td><![endif]-->\r\n    <!--[if (mso)|(IE)]></tr></table><![endif]-->\r\n    </div>\r\n  =20\r\n  </div>\r\n  <div id=3D"section-10" class=3D"hse-section" style=3D"padding-left:10px; =\r\npadding-right:10px">\r\n   =20\r\n   =20\r\n      <div class=3D"hse-column-container" style=3D"min-width:280px; max-wid=\r\nth:600px; margin:0 auto; background-color:#FFFFFF; padding-bottom:40px" bgc=\r\nolor=3D"#FFFFFF">\r\n   =20\r\n    <!--[if (mso)|(IE)]>\r\n      <table align=3D"center" style=3D"width:600px;" cellpadding=3D"0" cell=\r\nspacing=3D"0" role=3D"presentation" width=3D"600" bgcolor=3D"#FFFFFF">\r\n      <tr style=3D"background-color:#FFFFFF;">\r\n    <![endif]-->\r\n    <!--[if (mso)|(IE)]>\r\n  <td valign=3D"top" style=3D"width:600px;padding-bottom:40px;">\r\n<![endif]-->\r\n<!--[if gte mso 9]>\r\n  <table role=3D"presentation" width=3D"600" cellpadding=3D"0" cellspacing=\r\n=3D"0" style=3D"width:600px">\r\n<![endif]-->\r\n<div id=3D"column-10-0" class=3D"hse-column hse-size-12">\r\n  <div id=3D"hs_cos_wrapper_module-10-0-0" class=3D"hs_cos_wrapper hs_cos_w=\r\nrapper_widget hs_cos_wrapper_type_module" style=3D"color: inherit; font-siz=\r\ne: inherit; line-height: inherit;" data-hs-cos-general-type=3D"widget" data=\r\n-hs-cos-type=3D"module"><table class=3D"hse-image-wrapper" role=3D"presenta=\r\ntion" width=3D"100%" cellpadding=3D"0" cellspacing=3D"0">\r\n  <tbody>\r\n    <tr>\r\n      <td class=3D"hs_padded" align=3D"center" valign=3D"top" style=3D"font=\r\n-family:Arial, sans-serif; color:#333645; word-break:break-word; text-align=\r\n:center; padding:10px 20px; font-size:0px">\r\n        <a href=3D"https://email.mylighthouse.com/e3t/Ctc/ZR+113/ctkQp04/VV=\r\nBCnt19qf5NW62z2tX5PjQWSW5q0Twr5WY_lXN35KTBR5nR3bW69t95C6lZ3m-W7XCH-w18XYP2W=\r\n5mgh_n6HYZv4W1KNxzF1_pP8-W4jRKsd3tQ2V_W3hT2yQ6mgngCW15TzFf5TmC0JM75PGR_3qzf=\r\nW7X6FCb6q2rWfW8RYTPh6MhwYWW8KdBj-6XtztHW5HRn3L6lPCDTW8XPdyV42lVWRW8qGkJq5dM=\r\n3hCVzwZk630F1zrW8rdBsC617V_fW3ZXYKk6rydLm